INSERT INTO academy_courses (slug, title, description, icon, color, order_index, difficulty, requires_pro, is_published) VALUES
  ('dividends-income', 'Dividends & Passive Income', 'Some stocks pay you to hold them. Learn how dividend yield, payout ratio, and ex-dividend dates actually work.', 'Wallet', 'blue', 6, 'beginner', FALSE, TRUE)
ON CONFLICT (slug) DO NOTHING;

INSERT INTO academy_lessons (course_id, slug, title, type, order_index, xp_reward, content)
SELECT
  (SELECT id FROM academy_courses WHERE slug = 'dividends-income'),
  v.slug, v.title, v.type, v.order_index, v.xp_reward, v.content
FROM (VALUES
  ('what-is-a-dividend', 'What is a Dividend?', 'read', 0, 10, '{"sections":[{"text":"A dividend is a slice of a company''s profit that it pays out to its shareholders, usually as cash that lands right in your brokerage account. Think of it like being a part-owner of a lemonade stand: at the end of the month, the stand shares some of its earnings with everyone who owns a piece of it. Dividends are often paid every three months (that''s called quarterly).","highlightedTerms":[{"term":"Dividend","definition":"A cash payment a company sends to its shareholders out of its profit, usually every quarter."}]},{"text":"To see how much bang you get for your buck, investors look at the Dividend Yield. You calculate it by dividing the yearly dividend per share by the current stock price. For example, a stock priced at $100 that pays $3 a year has a 3% yield — so a $1,000 investment would earn you about $30 in dividends per year.","highlightedTerms":[{"term":"Dividend Yield","definition":"Annual dividend payments as a percentage of the stock price. A 3% yield means you''d earn $3 per year for every $100 invested — if dividends stay the same."}]},{"text":"Not every company pays a dividend, and that''s often a good thing! Fast-growing companies frequently keep all their profit and pour it back into the business — hiring, building, and inventing — hoping to grow much bigger later. This reinvested money often shows up as Retained Earnings, and investors bet the stock price will climb instead of getting paid cash today.","highlightedTerms":[{"term":"Retained Earnings","definition":"Cumulative profits the company has kept instead of paying out as dividends. Growing retained earnings usually means a healthy, profitable business."}]}],"funFact":"Some companies have raised their dividend every single year for over 50 years straight — they''re nicknamed ''Dividend Kings.''"}'::jsonb),
  ('payout-ratio-and-sustainability', 'Payout Ratio & Sustainability', 'read', 1, 10, '{"sections":[{"text":"When a company earns a profit, it can do two things with the money: keep it to grow the business, or hand some back to shareholders as a dividend. The payout ratio simply tells you how big that slice is. You calculate it by dividing the total Dividends Paid by the company''s Net Income (its bottom-line profit).","highlightedTerms":[{"term":"Dividends Paid","definition":"Total cash paid out to shareholders as dividends during the period."},{"term":"Net Income","definition":"The final profit after every cost — taxes, interest, and all other expenses — has been subtracted. The \"bottom line.\""}]},{"text":"Think of it like your own paycheck. If you earn $100 and give away $40, your ''payout ratio'' is 40% — comfortable, with plenty left over. But if you give away $95, you''re cutting it close, and any bad month could force you to stop. Companies work the same way: a lower ratio usually means the dividend has room to breathe.","highlightedTerms":[]},{"text":"As a rough guide, a payout ratio under about 60% often signals a safe, sustainable dividend. When it creeps above 80% — or over 100%, meaning the company pays out more than it earns — the dividend may be at risk of being cut. A cut can also drag down the stock price, so this ratio is a handy early warning sign.","highlightedTerms":[{"term":"Payout Ratio","definition":"Dividends paid divided by net income — the share of profit a company hands back to shareholders instead of keeping."}]},{"text":"One caution: profits can swing year to year, so a single high reading isn''t always alarming. Compare the payout ratio over several years and check that the company still generates healthy Free Cash Flow to actually fund those payments in real cash.","highlightedTerms":[{"term":"Free Cash Flow","definition":"Operating cash flow minus capital expenditures. Money the company can use to pay dividends, buy back shares, or pay down debt."}]}],"funFact":"Some companies proudly call themselves ''Dividend Aristocrats'' — a nickname for firms that have raised their dividend every year for at least 25 years straight, a streak that requires keeping the payout ratio in check."}'::jsonb),
  ('dividends-quiz', 'Quick Check: Dividends', 'quiz', 2, 20, '{"questions":[{"question":"A company''s stock costs $100 per share and pays $4 in dividends per year. What is its dividend yield?","options":["4%","25%","0.04%","40%"],"correctIndex":0,"explanation":"Dividend yield is the yearly dividend divided by the share price: $4 ÷ $100 = 4%. It tells you how much cash you earn each year for every dollar invested."},{"question":"A company earns $10 per share in profit and pays out $6 per share as dividends. What is its payout ratio?","options":["6%","167%","60%","40%"],"correctIndex":2,"explanation":"Payout ratio is dividends divided by earnings: $6 ÷ $10 = 60%. It shows what slice of profit goes to shareholders versus being kept to grow the business."},{"question":"To receive a company''s next dividend, when must you own the stock?","options":["You can buy it on the ex-dividend date and still get paid","You must own it before the ex-dividend date","Buying anytime that month guarantees the dividend","You must sell before the ex-dividend date"],"correctIndex":1,"explanation":"You need to own the shares before the ex-dividend date. If you buy on or after that date, the seller — not you — collects this round''s dividend."}]}'::jsonb),
  ('dividend-terms-match', 'Match the Dividend Terms', 'match', 3, 15, '{"pairs":[{"term":"Dividend Yield","definition":"The yearly dividend as a percentage of the stock''s price."},{"term":"Payout Ratio","definition":"The share of company profits paid out to shareholders as dividends."},{"term":"Ex-Dividend Date","definition":"The cutoff day — buy before it to get the next dividend."},{"term":"Dividend Aristocrat","definition":"A company that has raised its dividend every year for 25+ years."}]}'::jsonb),
  ('too-good-to-be-true', 'Too Good to Be True?', 'scenario', 4, 25, '{"setup":"You spot a stock paying a 15% dividend yield — that''s way higher than the 2-4% most companies pay. A dividend is a slice of profit the company sends to shareholders, and the yield is that payment as a percentage of the stock price. At 15%, a $1,000 investment would pay you $150 a year! But something feels off. What do you do before buying?","choices":[{"label":"Buy right away — a 15% yield means free money, and I don''t want to miss it.","feedback":"Hold on! A super-high yield is often a warning sign, not a gift. Yields go up when a stock''s price crashes. So a 15% yield might mean investors are dumping the stock because they expect the dividend to be cut. Chasing yield without checking why it''s so high is how people fall into a ''yield trap.''","isCorrect":false},{"label":"Check the payout ratio and why the stock price dropped, then decide.","feedback":"Exactly right. The payout ratio shows how much of the company''s profit is being paid out as dividends. If it''s over 100%, the company is paying out more than it earns — that dividend can''t last. And a recent price crash often means the market expects bad news. Investigating the business health protects you from a yield trap. Smart move.","isCorrect":true},{"label":"Ignore the payout ratio — as long as they''ve paid dividends before, they''ll keep paying.","feedback":"Past payments don''t guarantee future ones. Companies cut dividends all the time when profits fall — and often the stock price already dropped because investors saw it coming. Without checking the payout ratio and the business''s health, you''re guessing. Always look under the hood first.","isCorrect":false}]}'::jsonb)
) AS v(slug, title, type, order_index, xp_reward, content)
ON CONFLICT (course_id, slug) DO NOTHING;
